<?php
require_once 'connection/config.php';
require_once '__init.php';
require_once 'inc/functions.php';
require_once 'inc/Auth.php';
require_once 'inc/ParentWeeklyReport.php';
require_once 'inc/RecoveryPlan.php';

$pageName = 'student_learning_journey';
$subPageName = 'recovery_plan';
$conn = db();
$escape = static fn($value): string => htmlspecialchars((string) $value, ENT_QUOTES, 'UTF-8');
$base = rtrim((string) $baseUrl, '/');
$selectedStudentId = (int) ($_GET['student_id'] ?? 0);
$selectedCourseId = trim((string) ($_GET['course_id'] ?? ''));
$selectedPlanId = (int) ($_GET['plan_id'] ?? 0);
$courses = mmh_parent_report_courses($conn);
if ($selectedCourseId === '' && $selectedStudentId > 0) {
    $stmt = $conn->prepare('SELECT course_id FROM course_logs WHERE user_id = ? ORDER BY purchase_date DESC, id DESC LIMIT 1');
    if ($stmt) { $stmt->bind_param('i', $selectedStudentId); $stmt->execute(); $selectedCourseId = (string) (($stmt->get_result()->fetch_assoc()['course_id'] ?? '') ?: ''); $stmt->close(); }
}
if ($selectedCourseId === '') $selectedCourseId = (string) ($courses[0]['course_id'] ?? '');
$students = $selectedCourseId !== '' ? mmh_parent_report_students($conn, $selectedCourseId) : [];
if ($selectedStudentId <= 0 && $students) $selectedStudentId = (int) $students[0]['user_id'];
$availableItems = $selectedCourseId !== '' ? mmh_learning_journey_visible_items($conn, $selectedCourseId) : [];
$plans = ($selectedCourseId !== '' && $selectedStudentId > 0) ? mmh_recovery_plan_statuses($conn, $selectedStudentId, $selectedCourseId) : [];
if ($selectedPlanId <= 0) foreach ($plans as $candidate) { if (in_array((string) $candidate['status'], ['active', 'draft'], true)) { $selectedPlanId = (int) $candidate['id']; break; } }
$plan = ($selectedCourseId !== '' && $selectedStudentId > 0 && $selectedPlanId > 0) ? mmh_recovery_plan_load($conn, $selectedStudentId, $selectedCourseId, $selectedPlanId) : null;
if ($plan) $plan = mmh_recovery_plan_sync($conn, $plan, $selectedStudentId, $selectedCourseId);
$flash = $_SESSION['recovery_plan_flash'] ?? null;
unset($_SESSION['recovery_plan_flash']);
?>
