</style></head><body class="dash ds-bg-primary"><div class="col-12 d-flex"><?php include 'layouts/admin/aside.php'; ?><div class="main-content in-active"><?php include 'layouts/admin/top-nav.php'; ?><main class="recovery-admin">
<section class="recovery-card"><div class="recovery-header"><div><div class="course-manager-eyebrow">Student support</div><h1 class="h3 mb-1">Recovery Plan</h1><p class="recovery-help mb-0">Select existing published course items. Completion comes from Learning Journey and never changes LMS history.</p></div><form method="get" class="recovery-toolbar" action="<?= $escape($base . '/admin/recovery-plan') ?>"><label>Course<select name="course_id" class="form-control form-control-sm" onchange="this.form.submit()"><option value="">Select course</option><?php foreach ($courses as $course): ?><option value="<?= $escape($course['course_id']) ?>" <?= $selectedCourseId === (string) $course['course_id'] ? 'selected' : '' ?>><?= $escape($course['course_title']) ?></option><?php endforeach; ?></select></label><?php if ($selectedCourseId !== ''): ?><label>Student<select name="student_id" class="form-control form-control-sm" onchange="this.form.submit()"><option value="">Select student</option><?php foreach ($students as $student): ?><option value="<?= (int) $student['user_id'] ?>" <?= $selectedStudentId === (int) $student['user_id'] ? 'selected' : '' ?>><?= $escape($student['full_name'] ?: $student['username']) ?></option><?php endforeach; ?></select></label><?php endif; ?></form></div></section>
<?php if (is_array($flash)): ?><div class="alert alert-<?= !empty($flash['ok']) ? 'success' : 'danger' ?>"><?= $escape($flash['message'] ?? '') ?></div><?php endif; ?>
<?php if (!$selectedCourseId || !$selectedStudentId): ?><section class="recovery-card"><p class="recovery-help mb-0">Choose an enrolled course and student to manage a plan.</p></section>
