<section class="recovery-card"><div class="recovery-header"><div><h2 class="h5 mb-1">Plans for this student</h2><p class="recovery-help mb-0">Only one plan can be active. Drafts can be edited before activation.</p></div><div class="recovery-actions"><form method="post" action="<?= $escape($base . '/admin/requests/recovery-plan/save') ?>"><input type="hidden" name="_token" value="<?= $escape(mmh_auth_csrf_token()) ?>"><input type="hidden" name="course_id" value="<?= $escape($selectedCourseId) ?>"><input type="hidden" name="student_id" value="<?= (int) $selectedStudentId ?>"><input type="hidden" name="action" value="create"><button class="btn btn-primary btn-sm" type="submit">Create Recovery Plan</button></form><?php if ($plans): ?><label class="recovery-toolbar"><select class="form-control form-control-sm" aria-label="Select plan" onchange="if(this.value) window.location=this.value"><option value="">Select plan</option><?php foreach ($plans as $candidate): ?><option value="<?= $escape($base . '/admin/recovery-plan?course_id=' . rawurlencode($selectedCourseId) . '&student_id=' . (int) $selectedStudentId . '&plan_id=' . (int) $candidate['id']) ?>" <?= $selectedPlanId === (int) $candidate['id'] ? 'selected' : '' ?>><?= $escape($candidate['title']) ?> · <?= $escape(ucfirst($candidate['status'])) ?></option><?php endforeach; ?></select></label><?php endif; ?></div></div></section>
<?php if (!$plan): ?><section class="recovery-card"><p class="recovery-help mb-0">Create a plan to start selecting existing course items.</p></section>
<?php else: ?><form method="post" action="<?= $escape($base . '/admin/requests/recovery-plan/save') ?>"><input type="hidden" name="_token" value="<?= $escape(mmh_auth_csrf_token()) ?>"><input type="hidden" name="action" value="save"><input type="hidden" name="course_id" value="<?= $escape($selectedCourseId) ?>"><input type="hidden" name="student_id" value="<?= (int) $selectedStudentId ?>"><input type="hidden" name="plan_id" value="<?= (int) $plan['id'] ?>"><section class="recovery-card"><div class="recovery-header"><div><input class="form-control mb-2" name="title" value="<?= $escape($plan['title']) ?>" maxlength="180" aria-label="Recovery Plan title"><span class="recovery-status <?= $escape($plan['status']) ?>"><?= $escape(ucfirst($plan['status'])) ?></span><span class="ms-2"><?= (int) ($plan['required_completed'] ?? 0) ?> / <?= (int) ($plan['required_total'] ?? 0) ?> required complete</span></div><button class="btn btn-primary" type="submit">Save plan</button></div><div class="recovery-rows" id="recovery-rows">
<?php foreach (($plan['items'] ?? []) as $index => $item): ?><div class="recovery-row" data-recovery-row><span class="recovery-row-index" data-index><?= $index + 1 ?></span><select class="form-control form-control-sm" name="items[<?= $index ?>][item_id]" aria-label="Recovery item <?= $index + 1 ?>"><?php foreach ($availableItems as $available): ?><option value="<?= $escape($available['item_id']) ?>" <?= (string) $available['item_id'] === (string) $item['item_id'] ? 'selected' : '' ?>><?= $escape($available['item_title']) ?> · <?= $escape(mmh_recovery_plan_item_label($available)) ?></option><?php endforeach; ?></select><input class="form-control form-control-sm" type="number" name="items[<?= $index ?>][estimated_duration]" min="0" max="1440" value="<?= $item['estimated_duration'] === null ? '' : (int) $item['estimated_duration'] ?>" placeholder="Minutes" aria-label="Estimated duration"><input class="form-control form-control-sm" type="number" name="items[<?= $index ?>][weight]" min="0" step="0.01" value="<?= $item['weight'] === null ? '' : $escape($item['weight']) ?>" placeholder="Weight" aria-label="Weight"><div class="recovery-row-options"><label><input type="hidden" name="items[<?= $index ?>][required]" value="0"><input type="checkbox" name="items[<?= $index ?>][required]" value="1" <?= !empty($item['is_required']) ? 'checked' : '' ?>> Required</label><label><input type="hidden" name="items[<?= $index ?>][locked_until_previous]" value="0"><input type="checkbox" name="items[<?= $index ?>][locked_until_previous]" value="1" <?= !empty($item['locked_until_previous']) ? 'checked' : '' ?>> Lock until previous complete</label><span><?= $escape($item['section_title'] ?: 'General') ?> · <?= $escape(mmh_recovery_plan_item_label($item)) ?></span></div><textarea class="form-control form-control-sm" name="items[<?= $index ?>][teacher_note]" maxlength="1000" placeholder="Teacher note (optional)"><?= $escape($item['teacher_note']) ?></textarea><div class="recovery-row-actions"><button type="button" data-move="up" aria-label="Move item up">↑</button><button type="button" data-move="down" aria-label="Move item down">↓</button><button type="button" data-remove-row aria-label="Remove item">×</button></div></div><?php endforeach; ?></div><div class="recovery-actions mt-3"><select id="recovery-picker" class="form-control form-control-sm" aria-label="Add existing course item"><option value="">Choose existing item</option><?php foreach ($availableItems as $available): ?><option value="<?= $escape($available['item_id']) ?>"><?= $escape($available['item_title']) ?> · <?= $escape(mmh_recovery_plan_item_label($available)) ?></option><?php endforeach; ?></select><button class="btn btn-outline-secondary btn-sm" type="button" id="recovery-add">Add item</button></div></section></form>
<div class="recovery-actions mb-4"><form method="post" action="<?= $escape($base . '/admin/requests/recovery-plan/save') ?>"><input type="hidden" name="_token" value="<?= $escape(mmh_auth_csrf_token()) ?>"><input type="hidden" name="action" value="duplicate"><input type="hidden" name="course_id" value="<?= $escape($selectedCourseId) ?>"><input type="hidden" name="student_id" value="<?= (int) $selectedStudentId ?>"><input type="hidden" name="plan_id" value="<?= (int) $plan['id'] ?>"><button class="btn btn-outline-secondary btn-sm" type="submit">Duplicate as draft</button></form><?php if (($plan['status'] ?? '') === 'draft' || ($plan['status'] ?? '') === 'completed'): ?><form method="post" action="<?= $escape($base . '/admin/requests/recovery-plan/save') ?>"><input type="hidden" name="_token" value="<?= $escape(mmh_auth_csrf_token()) ?>"><input type="hidden" name="action" value="<?= $plan['status'] === 'draft' ? 'activate' : 'reopen' ?>"><input type="hidden" name="course_id" value="<?= $escape($selectedCourseId) ?>"><input type="hidden" name="student_id" value="<?= (int) $selectedStudentId ?>"><input type="hidden" name="plan_id" value="<?= (int) $plan['id'] ?>"><button class="btn btn-success btn-sm" type="submit"><?= $plan['status'] === 'draft' ? 'Activate plan' : 'Reopen plan' ?></button></form><?php endif; ?><form method="post" action="<?= $escape($base . '/admin/requests/recovery-plan/save') ?>"><input type="hidden" name="_token" value="<?= $escape(mmh_auth_csrf_token()) ?>"><input type="hidden" name="action" value="archive"><input type="hidden" name="course_id" value="<?= $escape($selectedCourseId) ?>"><input type="hidden" name="student_id" value="<?= (int) $selectedStudentId ?>"><input type="hidden" name="plan_id" value="<?= (int) $plan['id'] ?>"><button class="btn btn-outline-danger btn-sm" type="submit">Archive plan</button></form></div>
