</main></div></div>
<template id="recovery-template"><div class="recovery-row" data-recovery-row><span class="recovery-row-index" data-index></span><select class="form-control form-control-sm" name="items[__INDEX__][item_id]" aria-label="Recovery item"><option value="">Choose existing item</option><?php foreach ($availableItems as $available): ?><option value="<?= $escape($available['item_id']) ?>"><?= $escape($available['item_title']) ?> · <?= $escape(mmh_recovery_plan_item_label($available)) ?></option><?php endforeach; ?></select><input class="form-control form-control-sm" type="number" name="items[__INDEX__][estimated_duration]" min="0" max="1440" placeholder="Minutes" aria-label="Estimated duration"><input class="form-control form-control-sm" type="number" name="items[__INDEX__][weight]" min="0" step="0.01" placeholder="Weight" aria-label="Weight"><div class="recovery-row-options"><label><input type="hidden" name="items[__INDEX__][required]" value="0"><input type="checkbox" name="items[__INDEX__][required]" value="1" checked> Required</label><label><input type="hidden" name="items[__INDEX__][locked_until_previous]" value="0"><input type="checkbox" name="items[__INDEX__][locked_until_previous]" value="1"> Lock until previous complete</label></div><textarea class="form-control form-control-sm" name="items[__INDEX__][teacher_note]" maxlength="1000" placeholder="Teacher note (optional)"></textarea><div class="recovery-row-actions"><button type="button" data-move="up" aria-label="Move item up">↑</button><button type="button" data-move="down" aria-label="Move item down">↓</button><button type="button" data-remove-row aria-label="Remove item">×</button></div></div></template>
<script>
(function(){const list=document.getElementById('recovery-rows'),picker=document.getElementById('recovery-picker'),add=document.getElementById('recovery-add'),template=document.getElementById('recovery-template');if(!list||!picker||!add||!template)return;function renumber(){Array.from(list.querySelectorAll('[data-recovery-row]')).forEach(function(row,index){row.querySelector('[data-index]').textContent=index+1;row.querySelectorAll('[name]').forEach(function(input){input.name=input.name.replace(/items\[[^\]]+\]/,'items['+index+']');});});}add.addEventListener('click',function(){if(!picker.value)return;const fragment=template.content.cloneNode(true);const row=fragment.querySelector('[data-recovery-row]');row.querySelector('select').value=picker.value;list.appendChild(fragment);picker.value='';renumber();});list.addEventListener('click',function(event){const button=event.target.closest('button');if(!button)return;const row=button.closest('[data-recovery-row]');if(button.hasAttribute('data-remove-row')){row.remove();renumber();return;}const sibling=button.getAttribute('data-move')==='up'?row.previousElementSibling:row.nextElementSibling;if(sibling){if(button.getAttribute('data-move')==='up')list.insertBefore(row,sibling);else list.insertBefore(sibling,row);renumber();}});renumber();})();
</script></body></html>
